<script setup lang="ts">
import {computed,ref,useId} from 'vue';
import type {ExecutionPlan} from '../executionTypes';
import type {SharedStep} from '../systemScenario';
import {workflowContracts} from '../workflowTypes';
import TypedValueEditor from './TypedValueEditor.vue';
const props=defineProps<{step:SharedStep;plan:ExecutionPlan;previous:SharedStep[]}>();
const listId=useId();
const starts=computed(()=>props.previous.filter(s=>s.kind==='workflow_start'&&s.workflow));
const selected=computed(()=>props.step.kind==='workflow_start'?props.step.workflow?.workflowId:starts.value.find(s=>s.workflow?.instanceId===props.step.workflow?.instanceId)?.workflow?.workflowId);
const flow=computed(()=>props.plan.workflows?.find(f=>f.id===selected.value));
const contracts=computed(()=>flow.value?workflowContracts(flow.value.lock.workflow):[]);
const signalPorts=computed(()=>flow.value?.lock.workflow.signals.find(s=>s.name===props.step.workflow?.event?.signal)?.inputs||[]);
const responseNode=ref('');
const taskNode=computed(()=>flow.value?.lock.workflow.nodes.find(n=>n.task&&n.task.kind==='human'));
const responsePorts=computed(()=>props.step.workflow?.event?.kind==='signal'?signalPorts.value:(flow.value?.lock.workflow.nodes.find(n=>n.id===responseNode.value)||taskNode.value)?.task?.response||[]);
function chooseWorkflow(id:string){if(!props.step.workflow)return;props.step.workflow.workflowId=id;props.step.workflow.inputs={};props.step.workflow.faults={};}
function eventKind(kind:string){if(!props.step.workflow)return;props.step.workflow.event={id:'event1',kind:kind as 'signal'|'response',values:{},...(kind==='response'?{taskId:'task1'}:{signal:flow.value?.lock.workflow.signals[0]?.name||''})};}
</script>
<template><section v-if="step.workflow" class="workflow-step"><label>Workflow instance ID *<input v-model="step.workflow.instanceId" :list="step.kind==='workflow_start'?undefined:listId"/></label><datalist :id="listId"><option v-for="s in starts" :key="s.workflow!.instanceId" :value="s.workflow!.instanceId"/></datalist>
 <template v-if="step.kind==='workflow_start'"><label>Installed workflow *<select :value="step.workflow.workflowId" @change="chooseWorkflow(($event.target as HTMLSelectElement).value)"><option v-for="f in plan.workflows||[]" :key="f.id" :value="f.id">{{f.name}}</option></select></label><TypedValueEditor v-for="port in flow?.lock.workflow.inputs||[]" :key="port.name" :model-value="step.workflow.inputs?.[port.name]" :type="port.type" :record-ref="port.recordRef" :contracts="contracts" :label="port.name+' *'" @update:model-value="v=>{step.workflow!.inputs??={};if(v)step.workflow!.inputs[port.name]=v;else delete step.workflow!.inputs[port.name]}"/>
 <details><summary>Command fault injection</summary><label v-for="n in flow?.lock.workflow.nodes.filter(n=>n.command)||[]" :key="n.id">{{n.name}}<select :value="step.workflow.faults?.[n.id]||''" @change="step.workflow!.faults??={};($event.target as HTMLSelectElement).value?step.workflow!.faults[n.id]=($event.target as HTMLSelectElement).value:delete step.workflow!.faults[n.id]"><option value="">None</option><option value="before_commit">Rollback before commit</option></select></label></details><p>Starting the same instance with the same inputs reuses its checkpoint. A different instance gets its own workflow identity while using the configured shared owners.</p></template>
 <template v-else-if="step.kind==='workflow_event'&&step.workflow.event"><label>Event kind<select :value="step.workflow.event.kind" @change="eventKind(($event.target as HTMLSelectElement).value)"><option value="response">Human response</option><option value="signal">Signal</option></select></label><label>Event ID *<input v-model="step.workflow.event.id"/></label><label v-if="step.workflow.event.kind==='response'">Exact waiting task ID *<input v-model="step.workflow.event.taskId" placeholder="task1"/></label><label v-else>Signal *<select v-model="step.workflow.event.signal" @change="step.workflow!.event!.values={}"><option v-for="signal in flow?.lock.workflow.signals||[]" :key="signal.name">{{signal.name}}</option></select></label><label v-if="step.workflow.event.kind==='response'">Response contract<select v-model="responseNode" @change="step.workflow!.event!.values={}"><option value="">{{taskNode?.name||'Choose a human task'}}</option><option v-for="n in flow?.lock.workflow.nodes.filter(n=>n.task?.kind==='human')||[]" :key="n.id" :value="n.id">{{n.name}}</option></select></label><p>Use the task ID shown in the waiting trace. Broker tasks accept only their correlated acknowledgement. Reusing an event ID with the same payload replays its receipt.</p><TypedValueEditor v-for="port in responsePorts" :key="port.name" :model-value="step.workflow.event.values[port.name]" :type="port.type" :record-ref="port.recordRef" :contracts="contracts" :label="port.name" @update:model-value="v=>{if(v)step.workflow!.event!.values[port.name]=v;else delete step.workflow!.event!.values[port.name]}"/></template>
 <template v-else-if="step.kind==='workflow_deliver'||step.kind==='workflow_retry'"><label>Correlated broker task ID *<input v-model="step.workflow.taskId" placeholder="task2"/></label><label>Delivery fault<select v-model="step.workflow.fault"><option value="">None</option><option value="drop_before_receive">Drop before receipt</option><option value="before_recipient_commit">Rollback recipient</option><option value="after_recipient_commit_before_ack">Lose acknowledgement after commit</option></select></label><p>The workflow dispatched its intent automatically. This step controls delivery of that exact task’s frozen message.</p></template>
 <p v-else>Restore the modeled durable workflow checkpoint, including variables, waiting task and event receipts. No business commands are replayed.</p>
 <label>Expected workflow status (optional)<select v-model="step.expectedWorkflowStatus"><option value="">No assertion</option><option>waiting</option><option>completed</option><option>failed</option></select></label>
</section></template>
<style scoped>.workflow-step{min-width:0}label{display:grid;gap:6px;margin:10px 0}input,select{min-width:0;width:100%;box-sizing:border-box;padding:8px}p{font-size:12px;line-height:1.5}</style>
